+- [ ] **Step 5: Write src/scene.js**
+```javascript
+import * as THREE from 'three';
+
+export function initScene() {
+  const scene = new THREE.Scene();
+  scene.background = new THREE.Color(0xffffff);
+
+  const camera = new THREE.PerspectiveCamera(
+    75,
+    window.innerWidth / window.innerHeight,
+    0.1,
+    1000
+  );
+  camera.position.set(0, 3, 6);
+  camera.lookAt(0, 0, -5);
+
+  const renderer = new THREE.WebGLRenderer({ 
+    antialias: true,
+    powerPreference: "high-performance"
+  });
+  renderer.setSize(window.innerWidth, window.innerHeight);
+  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
+  document.getElementById('canvas-container').appendChild(renderer.domElement);
+
+  const light = new THREE.DirectionalLight(0xffffff, 1);
+  light.position.set(5, 10, 5);
+  scene.add(light);
+
+  scene.add(new THREE.AmbientLight(0xffffff, 0.5));
+
+  const onResize = () => {
+    camera.aspect = window.innerWidth / window.innerHeight;
+    camera.updateProjectionMatrix();
+    renderer.setSize(window.innerWidth, window.innerHeight);
+  };
+  window.addEventListener('resize', onResize);
+
+  return { scene, camera, renderer };
+}
+
+export function createPlayer() {
+  const geometry = new THREE.BoxGeometry(1, 1, 1);
+  const material = new THREE.MeshLambertMaterial({ color: 0x3498db });
+  const player = new THREE.Mesh(geometry, material);
+  player.position.y = 0.5;
+  return player;
+}
+
+export function createGround() {
+  const geometry = new THREE.PlaneGeometry(20, 100);
+  const material = new THREE.MeshLambertMaterial({ color: 0x95a5a6 });
+  const ground = new THREE.Mesh(geometry, material);
+  ground.rotation.x = -Math.PI / 2;
+  ground.position.z = -20;
+  return ground;
+}
+```
+
+- [ ] **Step 6: Write src/main.js (minimal)**
+```javascript
+import { initScene, createPlayer, createGround } from './scene.js';
+
+const { scene, camera, renderer } = initScene();
+
+const player = createPlayer();
+scene.add(player);
+
+const ground = createGround();
+scene.add(ground);
+
+function animate() {
+  requestAnimationFrame(animate);
+  renderer.render(scene, camera);
+}
+
+animate();
+```
+
+- [ ] **Step 7: Test the setup**
+Run: `npm install && npm run dev`
+Expected: Window opens with blue cube on gray floor, white background
+
+---
+
+### Task 2: Player Movement System
+
+**Files:**
+- Create: `src/player.js`
+- Modify: `src/main.js`
+
+**Interfaces:**
+- Consumes: `player` mesh from Task 1
+- Produces: `jump()` function, `setLane()` function, `update(delta)` function
+
+- [ ] **Step 1: Write src/player.js**
+```javascript
+const LANE_WIDTH = 3;
+const LANE_POSITIONS = [-LANE_WIDTH, 0, LANE_WIDTH];
+
+const JUMP_FORCE = 15;
+const GRAVITY = 30;
+
+let currentLane = 1; // Center lane
+let velocityY = 0;
+let isJumping = false;
+
+export function setLane(direction) {
+  // direction: -1 (left), 0 (stay), 1 (right)
+  currentLane = Math.max(0, Math.min(2, currentLane + direction));
+}
+
+export function jump() {
+  if (!isJumping) {
+    isJumping = true;
+    velocityY = JUMP_FORCE;
+  }
+}
+
+export function update(delta) {
+  // Update vertical position
+  if (isJumping) {
+    velocityY -= GRAVITY * delta;
+    player.position.y += velocityY * delta;
+    
+    if (player.position.y <= 0.5) {
+      player.position.y = 0.5;
+      velocityY = 0;
+      isJumping = false;
+    }
+  }
+
+  // Update horizontal position (smooth lane transition)
+  const targetX = LANE_POSITIONS[currentLane];
+  player.position.x += (targetX - player.position.x) * 10 * delta;
+
+  // Visual rotation during jump
+  if (isJumping) {
+    player.rotation.x += 3 * delta;
+  }
+}
+
+export function getLane() {
+  return currentLane;
+}
+
+export function reset() {
+  currentLane = 1;
+  velocityY = 0;
+  isJumping = false;
+  player.position.set(0, 0.5, 0);
+  player.rotation.set(0, 0, 0);
+}
+```
+
+- [ ] **Step 2: Modify src/main.js to use player module**
+```javascript
+import { initScene, createPlayer, createGround } from './scene.js';
+import { update: updatePlayer, reset: resetPlayer } from './player.js';
+
+const { scene, camera, renderer } = initScene();
+
+const player = createPlayer();
+scene.add(player);
+
+const ground = createGround();
+scene.add(ground);
+
+let lastTime = performance.now();
+
+function animate() {
+  const now = performance.now();
+  const delta = (now - lastTime) / 1000;
+  lastTime = now;
+
+  updatePlayer(delta);
+  renderer.render(scene, camera);
+  requestAnimationFrame(animate);
+}
+
+animate();
+```
+
+- [ ] **Step 3: Test player movement**
+Add temporary test controls to verify jump and lane switching work
+
+---
+
+### Task 3: Input Handling
+
+**Files:**
+- Modify: `src/main.js`
+
+**Interfaces:**
+- Consumes: `setLane()`, `jump()` from player module
+- Produces: Event listeners for keyboard and touch
+
+- [ ] **Step 1: Add keyboard input to src/main.js**
+```javascript
+document.addEventListener('keydown', (e) => {
+  switch (e.code) {
+    case 'Space':
+    case 'ArrowUp':
+      jump();
+      break;
+    case 'ArrowLeft':
+      setLane(-1);
+      break;
+    case 'ArrowRight':
+      setLane(1);
+      break;
+  }
+});
+```
+
+- [ ] **Step 2: Add touch/swipe input to src/main.js**
+```javascript
+let touchStartX = 0;
+let touchStartY = 0;
+
+document.addEventListener('touchstart', (e) => {
+  touchStartX = e.touches[0].clientX;
+  touchStartY = e.touches[0].clientY;
+});
+
+document.addEventListener('touchend', (e) => {
+  const touchEndX = e.changedTouches[0].clientX;
+  const touchEndY = e.changedTouches[0].clientY;
+  
+  const deltaX = touchEndX - touchStartX;
+  const deltaY = touchEndY - touchStartY;
+  
+  // Tap (jump)
+  if (Math.abs(deltaX) < 30 && Math.abs(deltaY) < 30) {
+    jump();
+  }
+  
+  // Swipe (lane change)
+  if (Math.abs(deltaX) > Math.abs(deltaY) && Math.abs(deltaX) > 30) {
+    setLane(deltaX > 0 ? 1 : -1);
+  }
+});
+```
+
+- [ ] **Step 3: Test all input methods**
+Verify keyboard (arrows/space), tap, and swipe all work correctly
+
+---
+
+### Task 4: Obstacle Spawning & Movement
+
+**Files:**
+- Create: `src/obstacles.js`
+- Modify: `src/main.js`
+
+**Interfaces:**
+- Consumes: `scene` from Task 1
+- Produces: `spawnObstacle()`, `updateObstacles()`, `resetObstacles()` functions
+
+- [ ] **Step 1: Write src/obstacles.js**
+```javascript
+import * as THREE from 'three';
+
+const obstacles = [];
+const MIN_SPAWN_DISTANCE = 5;
+const MAX_SPAWN_DISTANCE = 15;
+
+export function spawnObstacle() {
+  const geometry = new THREE.BoxGeometry(1, 
+    Math.random() * 3 + 2, // Height: 2-5
+    1);
+  const material = new THREE.MeshLambertMaterial({ color: 0xe74c3c });
+  const obstacle = new THREE.Mesh(geometry, material);
+  
+  const lane = Math.floor(Math.random() * 3);
+  obstacle.position.set(
+    [ -3, 0, 3][lane],
+    geometry.parameters.height / 2,
+    -50 // Spawn far ahead
+  );
+  
+  scene.add(obstacle);
+  obstacles.push(obstacle);
+  
+  return obstacle;
+}
+
+export function updateObstacles(speed, deltaTime) {
+  // Move all obstacles toward player
+  for (let i = obstacles.length - 1; i >= 0; i--) {
+    const obs = obstacles[i];
+    obs.position.z += speed * deltaTime;
+    
+    // Remove if passed player
+    if (obs.position.z > 2) {
+      scene.remove(obs);
+      obstacles.splice(i, 1);
+    }
+  }
+}
+
+export function resetObstacles() {
+  for (const obs of obstacles) {
+    scene.remove(obs);
+  }
+  obstacles.length = 0;
+}
+
+export function getObstacles() {
+  return obstacles;
+}
+
+export function getNextSpawnDistance() {
+  return MIN_SPAWN_DISTANCE + Math.random() * (MAX_SPAWN_DISTANCE - MIN_SPAWN_DISTANCE);
+}
+```
+
+- [ ] **Step 2: Modify src/main.js to integrate obstacles**
+```javascript
+import { spawnObstacle, updateObstacles, resetObstacles } from './obstacles.js';
+
+let gameSpeed = 10;
+let nextObstacleZ = -50;
+
+// ... inside animate function, before render ...
+updateObstacles(gameSpeed, delta);
+
+// Spawn new obstacle when needed
+if (obstacles.length === 0 || obstacles[obstacles.length - 1].position.z < nextObstacleZ) {
+  spawnObstacle();
+  nextObstacleZ = obstacles[obstacles.length - 1].position.z + getNextSpawnDistance();
+}
+
+// Increase speed over time
+gameSpeed += 0.0005; // +1 unit every ~30 seconds
+```
+
+- [ ] **Step 3: Test obstacle spawning**
+Verify obstacles spawn randomly in different lanes and move toward player
+
+---
+
+### Task 5: Collision Detection & Game Over
+
+**Files:**
+- Create: `src/collision.js`
+- Modify: `src/main.js`
+
+**Interfaces:**
+- Consumes: `player`, `getObstacles()`
+- Produces: `checkCollision()` function
+
+- [ ] **Step 1: Write src/collision.js**
+```javascript
+import { getObstacles } from './obstacles.js';
+
+export function checkCollision() {
+  const player = scene.children.find(c => c.isMesh && c.material.color?.getHex() === 0x3498db);
+  if (!player) return false;
+  
+  const playerBox = new THREE.Box3().setFromObject(player);
+  
+  for (const obstacle of getObstacles()) {
+    const obstacleBox = new THREE.Box3().setFromObject(obstacle);
+    if (playerBox.intersectsBox(obstacleBox)) {
+      return true;
+    }
+  }
+  
+  return false;
+}
+```
+
+- [ ] **Step 2: Modify src/main.js to handle collisions**
+```javascript
+import { checkCollision } from './collision.js';
+
+let gameState = 'start'; // 'start', 'playing', 'gameover'
+let score = 0;
+
+// ... inside animate function ...
+if (gameState === 'playing') {
+  if (checkCollision()) {
+    gameOver();
+  }
+  
+  // Update score based on distance
+  score = Math.floor(-ground.position.z / 10);
+  document.getElementById('score').textContent = `Score: ${score}`;
+}
+
+function gameOver() {
+  gameState = 'gameover';
+  document.getElementById('game-over').style.display = 'block';
+  document.getElementById('final-score').textContent = score;
+  document.getElementById('best-score').textContent = getHighScore();
+}
+```
+
+- [ ] **Step 3: Test collision detection**
+Verify game-over triggers when player hits obstacle
+
+---
+
+### Task 6: Game Flow & UI
+
+**Files:**
+- Modify: `src/main.js`
+
+**Interfaces:**
+- Consumes: UI elements from index.html
+- Produces: Start/reset game logic
+
+- [ ] **Step 1: Add game flow controls to src/main.js**
+```javascript
+import { reset: resetPlayer } from './player.js';
