+}
+
+function resetGame() {
+  gameState = 'start';
+  ground.position.z = -20;
+  
+  startScreen.style.display = 'block';
+  hud.style.display = 'none';
+  gameOverScreen.style.display = 'none';
+}
+
+startScreen.addEventListener('click', startGame);
+startScreen.addEventListener('touchstart', (e) => { e.preventDefault(); startGame(); });
+restartBtn.addEventListener('click', startGame);
+```
+
+- [ ] **Step 2: Test game flow**
+Verify start, playing, and game-over states transition correctly
+
+---
+
+### Task 7: High Score Persistence
+
+**Files:**
+- Create: `src/storage.js`
+- Modify: `src/main.js`
+
+**Interfaces:**
+- Produces: `getHighScore()`, `saveHighScore()` functions
+
+- [ ] **Step 1: Write src/storage.js**
+```javascript
+const STORAGE_KEY = '3d-runner-highscore';
+
+export function getHighScore() {
+  return parseInt(localStorage.getItem(STORAGE_KEY) || '0');
+}
+
+export function saveHighScore(score) {
+  const current = getHighScore();
+  if (score > current) {
+    localStorage.setItem(STORAGE_KEY, score.toString());
+  }
+}
+```
+
+- [ ] **Step 2: Modify src/main.js to save high score**
